def solve_grid_v2(test_in):
    """
    New approach: Each input value spawns diagonals from ALL 4 block corners.
    """
    n = len(test_in)

    # Find block
    block_r, block_c = None, None
    for r in range(n):
        for c in range(n):
            if test_in[r][c] == 2:
                if (r+1 < n and c+1 < n and 
                    test_in[r+1][c] == 2 and test_in[r+1][c+1] == 2):
                    block_r, block_c = r, c
                    break

    output = [[0]*n for _ in range(n)]

    print(f"Block at ({block_r}, {block_c})")

    for r in range(n):
        for c in range(n):
            val = test_in[r][c]
            if val == 0 or val == 2:
                continue

            input_ab = r < block_r
            input_bd = r > block_r + 1
            input_lft = c < block_c
            input_rgt = c > block_c + 1

            if val % 2 == 1:
                diag_type = 'anti'
            else:
                diag_type = 'main'

            print(f"\nValue {val} at ({r},{c}): {diag_type}")
            print(f"  Quadrants: above={input_ab}, below={input_bd}, left={input_lft}, right={input_rgt}")

            # UL: above AND left
            if input_ab and input_lft:
                start_r, start_c = block_r - 1, block_c - 1
                if diag_type == 'anti':
                    dr, dc = 1, 1
                else:
                    dr, dc = 1, -1
                rr, cc = start_r, start_c
                while 0 <= rr < n and 0 <= cc < n:
                    output[rr][cc] = val
                    rr += dr; cc += dc

            # UR: above AND right
            if input_ab and input_rgt:
                start_r, start_c = block_r - 1, block_c + 1
                if diag_type == 'anti':
                    dr, dc = 1, -1
                else:
                    dr, dc = 1, 1
                rr, cc = start_r, start_c
                while 0 <= rr < n and 0 <= cc < n:
                    output[rr][cc] = val
                    rr += dr; cc += dc

            # DL: below AND left
            if input_bd and input_lft:
                start_r, start_c = block_r + 1, block_c - 1
                if diag_type == 'anti':
                    dr, dc = -1, 1
                else:
                    dr, dc = -1, -1
                rr, cc = start_r, start_c
                while 0 <= rr < n and 0 <= cc < n:
                    output[rr][cc] = val
                    rr += dr; cc += dc

            # DR: below AND right
            if input_bd and input_rgt:
                start_r, start_c = block_r + 1, block_c + 1
                if diag_type == 'anti':
                    dr, dc = -1, -1
                else:
                    dr, dc = -1, 1
                rr, cc = start_r, start_c
                while 0 <= rr < n and 0 <= cc < n:
                    output[rr][cc] = val
                    rr += dr; cc += dc

    return output

output = solve_grid_v2(test_in)

print("\n\nGenerated output:")
for row in output:
    print(" ".join(str(x) for x in row))

print("\n\nFormatted test output:")
